3.4 De contagens a indicadores

indicadores &lt;- agregados_ana |&gt;
  mutate(
    dens_hab_ha = populacao / (area_km2 * 100),
    moradores_por_dom = populacao / domicilios
  )

4.2 Leitura dos microdados

library(censobr)
library(dplyr)

pessoas &lt;- read_population(year = 2022, as_data_frame = FALSE)

pessoas_ana &lt;- pessoas |&gt;
  filter(code_muni == "5201108") |&gt;
  select(code_weighting, peso, idade, sexo, rendimento, desloc_trabalho, tempo_desloc) |&gt;
  collect()

4.4 Declaração do desenho amostral

library(srvyr)

desenho &lt;- pessoas_ana |&gt;
  as_survey_design(weights = peso, strata = code_weighting)

desenho |&gt;
  group_by(code_weighting) |&gt;
  summarise(renda_media = survey_mean(rendimento, na.rm = TRUE))

5.4 Agregação de destinos

library(sf)

cnefe_sf &lt;- cnefe_ana |&gt;
  filter(!is.na(longitude), !is.na(latitude)) |&gt;
  st_as_sf(coords = c("longitude", "latitude"), crs = 4674)

6.4 Preparação das origens e destinos

pontos &lt;- grade_ana |&gt;
  filter(populacao &gt; 0) |&gt;
  st_centroid() |&gt;
  st_transform(4326)

# formato exigido pelo r5r
pontos_r5 &lt;- pontos |&gt;
  mutate(
    id  = as.character(id_grade),
    lon = st_coordinates(geometry)[, 1],
    lat = st_coordinates(geometry)[, 2]
  ) |&gt;
  st_drop_geometry()







DicaFim da Parte 1



O arquivo de pontos produzido aqui reúne, em uma mesma tabela, onde as pessoas moram e onde estão as oportunidades. É com ele que a Parte 2 começa.
